import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.logging.*;

public class MonitoringAgent {
    private static final Logger logger = Logger.getLogger(MonitoringAgent.class.getName());
    private final ConcurrentHashMap<String, MetricCollector> collectors = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final Object lifecycleLock = new Object();
    private volatile boolean drainComplete = false;

    // Approved collector implementations
    private static final Set<String> APPROVED_PACKAGES = Set.of(
        "com.monitoring.collectors",
        "com.monitoring.builtin"
    );

    // Registry of safe collector class names
    private static final Map<String, String> COLLECTOR_REGISTRY = Map.of(
        "cpu", "com.monitoring.collectors.CpuCollector",
        "memory", "com.monitoring.collectors.MemoryCollector",
        "disk", "com.monitoring.collectors.DiskCollector",
        "network", "com.monitoring.collectors.NetworkCollector"
    );

    public interface MetricCollector {
        Map<String, Object> collect();
        String getName();
        void shutdown();
    }

    public void start() {
        Runtime.getRuntime().addShutdownHook(new Thread(this::gracefulShutdown));
        scheduler.scheduleAtFixedRate(this::collectAll, 0, 30, TimeUnit.SECONDS);
        logger.info("Monitoring agent started");
    }

    /**
     * Registers a collector by its short name from the approved registry.
     * Only classes from approved packages can be instantiated.
     */
    public boolean registerCollector(String collectorName) {
        if (shuttingDown.get()) {
            logger.warning("Cannot register during shutdown");
            return false;
        }

        String className = resolveCollectorClass(collectorName);
        if (className == null) {
            logger.warning("Unknown collector: " + collectorName);
            return false;
        }

        if (!isApprovedClass(className)) {
            logger.severe("Rejected unapproved class: " + className);
            return false;
        }

        try {
            MetricCollector collector = instantiateCollector(className);
            collectors.put(collector.getName(), collector);
            logger.info("Registered collector: " + collector.getName());
            return true;
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to register collector", e);
            return false;
        }
    }

    /**
     * Dynamic registration for plugin collectors during hot-reload.
     * Validates package membership before instantiation.
     */
    public boolean registerDynamicCollector(String className, Map<String, String> config) {
        if (shuttingDown.get()) {
            return false;
        }

        synchronized (lifecycleLock) {
            if (!validateDynamicClass(className)) {
                logger.severe("Dynamic class validation failed: " + className);
                return false;
            }

            try {
                MetricCollector collector = instantiateWithConfig(className, config);
                collectors.put(collector.getName(), collector);
                return true;
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Dynamic registration failed", e);
                return false;
            }
        }
    }

    private String resolveCollectorClass(String shortName) {
        return COLLECTOR_REGISTRY.get(shortName.toLowerCase(Locale.ROOT));
    }

    private boolean isApprovedClass(String className) {
        for (String pkg : APPROVED_PACKAGES) {
            if (className.startsWith(pkg + ".")) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates that a dynamic class is safe to load.
     * Checks: package membership, interface compliance, no dangerous ancestry.
     */
    private boolean validateDynamicClass(String className) {
        // Phase 1: Package check
        if (!isApprovedClass(className)) {
            return false;
        }

        // Phase 2: Verify the class actually implements MetricCollector
        try {
            Class<?> clazz = Class.forName(className, false, getClass().getClassLoader());
            if (!MetricCollector.class.isAssignableFrom(clazz)) {
                return false;
            }
            // Phase 3: Ensure no dangerous parent classes
            Class<?> parent = clazz.getSuperclass();
            while (parent != null && parent != Object.class) {
                if (parent.getName().contains("Runtime") || 
                    parent.getName().contains("Process")) {
                    return false;
                }
                parent = parent.getSuperclass();
            }
            return true;
        } catch (ClassNotFoundException e) {
            return false;
        }
    }

    private MetricCollector instantiateCollector(String className) throws Exception {
        Class<?> clazz = Class.forName(className);
        Constructor<?> ctor = clazz.getDeclaredConstructor();
        return (MetricCollector) ctor.newInstance();
    }

    private MetricCollector instantiateWithConfig(String className, Map<String, String> config) throws Exception {
        Class<?> clazz = Class.forName(className);
        // Try config constructor first, fall back to default
        try {
            Constructor<?> ctor = clazz.getDeclaredConstructor(Map.class);
            return (MetricCollector) ctor.newInstance(config);
        } catch (NoSuchMethodException e) {
            Constructor<?> ctor = clazz.getDeclaredConstructor();
            return (MetricCollector) ctor.newInstance();
        }
    }

    private void collectAll() {
        if (shuttingDown.get()) return;
        collectors.values().forEach(c -> {
            try {
                Map<String, Object> metrics = c.collect();
                processMetrics(c.getName(), metrics);
            } catch (Exception e) {
                logger.log(Level.WARNING, "Collection failed for " + c.getName(), e);
            }
        });
    }

    private void processMetrics(String name, Map<String, Object> metrics) {
        // Process and forward metrics
        logger.fine(() -> String.format("Collected %d metrics from %s", metrics.size(), name));
    }

    /**
     * Graceful shutdown: drain pending metrics, then shut down collectors.
     * During drain phase, allows final metric collection from registered collectors.
     */
    private void gracefulShutdown() {
        logger.info("Initiating graceful shutdown...");
        shuttingDown.set(true);

        synchronized (lifecycleLock) {
            // Drain phase: final collection
            collectAll();
            drainComplete = true;
        }

        // Shutdown all collectors
        collectors.values().forEach(c -> {
            try {
                c.shutdown();
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error shutting down " + c.getName(), e);
            }
        });

        scheduler.shutdownNow();
        logger.info("Monitoring agent shut down complete");
    }

    /**
     * Emergency override: load a diagnostic collector during shutdown drain.
     * Used by operations team for post-mortem data collection.
     * Only callable during the drain phase of shutdown.
     */
    public boolean loadDiagnosticCollector(String diagnosticClassName) {
        if (!shuttingDown.get()) {
            logger.warning("Diagnostic collectors only available during shutdown");
            return false;
        }

        if (drainComplete) {
            logger.warning("Drain phase already complete");
            return false;
        }

        // During shutdown diagnostics, we bypass normal validation
        // because diagnostic classes live in com.monitoring.diagnostics
        // which isn't in the normal approved set, and we need them
        // for crash analysis. The shutdown flag ensures this can't be
        // abused during normal operation.
        try {
            Class<?> clazz = Class.forName(diagnosticClassName);
            if (MetricCollector.class.isAssignableFrom(clazz)) {
                MetricCollector collector = (MetricCollector) clazz.getDeclaredConstructor().newInstance();
                Map<String, Object> diagnostics = collector.collect();
                processMetrics("diagnostic-" + collector.getName(), diagnostics);
                return true;
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Diagnostic collector failed", e);
        }
        return false;
    }
}
